// WorkoutServiceServer is the server API for WorkoutService service.
// All implementations must embed UnimplementedWorkoutServiceServer
// for forward compatibility.
type WorkoutServiceServer interface {
	ListWorkouts(context.Context, *ListWorkoutsRequest) (*ListWorkoutsResponse, error)
	GetWorkout(context.Context, *GetWorkoutRequest) (*GetWorkoutResponse, error)
	LogDayWorkout(context.Context, *LogDayWorkoutRequest) (*LogDayWorkoutResponse, error)
	ListHistory(context.Context, *ListHistoryRequest) (*ListHistoryResponse, error)
	GetForgeStats(context.Context, *GetForgeStatsRequest) (*GetForgeStatsResponse, error)
	SubmitFeedback(context.Context, *SubmitFeedbackRequest) (*SubmitFeedbackResponse, error)
	// F7.2 — the Today screen snapshot.
	GetToday(context.Context, *GetTodayRequest) (*GetTodayResponse, error)
	// F7.3 — the forge rank ladder with metric requirements.
	GetRankLadder(context.Context, *GetRankLadderRequest) (*GetRankLadderResponse, error)
	// F7.1 — movement library + session builder + live session.
	ListExercises(context.Context, *ListExercisesRequest) (*ListExercisesResponse, error)
	CreateSession(context.Context, *CreateSessionRequest) (*CreateSessionResponse, error)
	GetSession(context.Context, *GetSessionRequest) (*GetSessionResponse, error)
	GetActiveSession(context.Context, *GetActiveSessionRequest) (*GetActiveSessionResponse, error)
	ListSessions(context.Context, *ListSessionsRequest) (*ListSessionsResponse, error)
	UpdateSessionStatus(context.Context, *UpdateSessionStatusRequest) (*UpdateSessionStatusResponse, error)
	LogSet(context.Context, *LogSetRequest) (*LogSetResponse, error)
	// F7.5 — streak ledger with weekly grace day. The Today snapshot
	// already embeds the streak; this RPC is for a dedicated detail
	// surface and for forced refresh after session completion.
	GetForgeStreak(context.Context, *GetForgeStreakRequest) (*GetForgeStreakResponse, error)
	// F7.6 — form-video capture path. The bytes go through the
	// existing MediaService presigned-URL flow; these RPCs link the
	// resulting media asset to a lifter + movement + set context, and
	// let the lifter review / archive their library.
	CreateFormVideo(context.Context, *CreateFormVideoRequest) (*CreateFormVideoResponse, error)
	ListMyFormVideos(context.Context, *ListMyFormVideosRequest) (*ListMyFormVideosResponse, error)
	DeleteFormVideo(context.Context, *DeleteFormVideoRequest) (*DeleteFormVideoResponse, error)
	UpdateFormVideoStatus(context.Context, *UpdateFormVideoStatusRequest) (*UpdateFormVideoStatusResponse, error)
	// F7P2.1 — programme browser, enrolment ledger, and the manual
	// week-advance the Phase 2 surface uses.
	ListProgrammes(context.Context, *ListProgrammesRequest) (*ListProgrammesResponse, error)
	GetProgramme(context.Context, *GetProgrammeRequest) (*GetProgrammeResponse, error)
	EnrolInProgramme(context.Context, *EnrolInProgrammeRequest) (*EnrolInProgrammeResponse, error)
	GetActiveEnrolment(context.Context, *GetActiveEnrolmentRequest) (*GetActiveEnrolmentResponse, error)
	ListMyEnrolments(context.Context, *ListMyEnrolmentsRequest) (*ListMyEnrolmentsResponse, error)
	UpdateEnrolment(context.Context, *UpdateEnrolmentRequest) (*UpdateEnrolmentResponse, error)
	// F7P2.1 follow-on — per-week prescriptions.
	ListProgrammeWeeks(context.Context, *ListProgrammeWeeksRequest) (*ListProgrammeWeeksResponse, error)
	GetProgrammeWeek(context.Context, *GetProgrammeWeekRequest) (*GetProgrammeWeekResponse, error)
	// F7P2.2 — personal records. Detection itself runs as a River
	// worker fired on session completion; these RPCs are read-only.
	ListMyPRs(context.Context, *ListMyPRsRequest) (*ListMyPRsResponse, error)
	ListRecentPRs(context.Context, *ListRecentPRsRequest) (*ListRecentPRsResponse, error)
	// F7P2.3 — body record. The composition timeline, injury log, and
	// annual mobility baseline are the three primitives that the
	// programming engine references permanently.
	ListBodyCompositions(context.Context, *ListBodyCompositionsRequest) (*ListBodyCompositionsResponse, error)
	CreateBodyComposition(context.Context, *CreateBodyCompositionRequest) (*CreateBodyCompositionResponse, error)
	DeleteBodyComposition(context.Context, *DeleteBodyCompositionRequest) (*DeleteBodyCompositionResponse, error)
	ListInjuries(context.Context, *ListInjuriesRequest) (*ListInjuriesResponse, error)
	CreateInjury(context.Context, *CreateInjuryRequest) (*CreateInjuryResponse, error)
	UpdateInjuryStatus(context.Context, *UpdateInjuryStatusRequest) (*UpdateInjuryStatusResponse, error)
	DeleteInjury(context.Context, *DeleteInjuryRequest) (*DeleteInjuryResponse, error)
	ListMobilityBaselines(context.Context, *ListMobilityBaselinesRequest) (*ListMobilityBaselinesResponse, error)
	GetCurrentMobilityBaseline(context.Context, *GetCurrentMobilityBaselineRequest) (*GetCurrentMobilityBaselineResponse, error)
	UpsertMobilityBaseline(context.Context, *UpsertMobilityBaselineRequest) (*UpsertMobilityBaselineResponse, error)
	DeleteMobilityBaseline(context.Context, *DeleteMobilityBaselineRequest) (*DeleteMobilityBaselineResponse, error)
	// F7P2.4 — wearable connectors + parity dashboard. The connection
	// and per-metric priority ledger; cloud reading ingestion (OAuth
	// pulls from Whoop / Oura / Garmin) is deferred.
	ListSensorConnections(context.Context, *ListSensorConnectionsRequest) (*ListSensorConnectionsResponse, error)
	SetSensorConnectionStatus(context.Context, *SetSensorConnectionStatusRequest) (*SetSensorConnectionStatusResponse, error)
	MarkSensorSynced(context.Context, *MarkSensorSyncedRequest) (*MarkSensorSyncedResponse, error)
	SetSensorPriority(context.Context, *SetSensorPriorityRequest) (*SetSensorPriorityResponse, error)
	// F7P2.6 — the training-science snapshot (acute:chronic ratio,
	// estimated 1RM, volume/intensity/frequency). Aggregation here,
	// math in services_rust/scoring.
	GetForgeAnalytics(context.Context, *GetForgeAnalyticsRequest) (*GetForgeAnalyticsResponse, error)
	// F7P2.7 — Session Replay & Analytics
	GetSessionAnalytics(context.Context, *GetSessionAnalyticsRequest) (*GetSessionAnalyticsResponse, error)
	// F7P2.8 — Equipment Vault
	ListUserEquipment(context.Context, *ListUserEquipmentRequest) (*ListUserEquipmentResponse, error)
	AddUserEquipment(context.Context, *AddUserEquipmentRequest) (*AddUserEquipmentResponse, error)
	DeleteUserEquipment(context.Context, *DeleteUserEquipmentRequest) (*DeleteUserEquipmentResponse, error)
	// F7P2.9 — Workout Rivalries
	ListWorkoutRivalries(context.Context, *ListWorkoutRivalriesRequest) (*ListWorkoutRivalriesResponse, error)
	GetRivalryDetail(context.Context, *GetRivalryDetailRequest) (*GetRivalryDetailResponse, error)
	// F7P3.1 — What-if simulator. Project the forge-rank / Power / Agility /
	// Grit change a hypothetical session would produce, via the Rust engine,
	// without committing anything.
	SimulateForgeRank(context.Context, *SimulateForgeRankRequest) (*SimulateForgeRankResponse, error)
	// F7P3.2 — Recovery score. A 0-100 readiness gate composed from the
	// lifter's recent training load (acute:chronic), streak momentum, and —
	// when available — the Apex cross-pillar readiness signal (HRV / RHR /
	// sleep). Drives the Today ring and the auto-deload nudge.
	GetRecoveryScore(context.Context, *GetRecoveryScoreRequest) (*GetRecoveryScoreResponse, error)
	// F7P3.3 — Coach concierge (Sovereign white-glove desk). Threaded
	// member ↔ coach messaging with an SLA timer.
	StartCoachThread(context.Context, *StartCoachThreadRequest) (*StartCoachThreadResponse, error)
	ListMyCoachThreads(context.Context, *ListMyCoachThreadsRequest) (*ListMyCoachThreadsResponse, error)
	GetCoachThread(context.Context, *GetCoachThreadRequest) (*GetCoachThreadResponse, error)
	PostCoachMessage(context.Context, *PostCoachMessageRequest) (*PostCoachMessageResponse, error)
	// F7P3.4 — Forge Anthology (named-author editorial long-reads).
	ListAnthologyArticles(context.Context, *ListAnthologyArticlesRequest) (*ListAnthologyArticlesResponse, error)
	GetAnthologyArticle(context.Context, *GetAnthologyArticleRequest) (*GetAnthologyArticleResponse, error)
	// F7P3.5 — public athlete share. Mints a time-bound token backing a
	// read-only public profile (rank + stats + PRs) at
	// /share/athlete/:token, content-negotiated HTML / JSON.
	CreateAthleteShare(context.Context, *CreateAthleteShareRequest) (*CreateAthleteShareResponse, error)
	ListMyAthleteShares(context.Context, *ListMyAthleteSharesRequest) (*ListMyAthleteSharesResponse, error)
	RevokeAthleteShare(context.Context, *RevokeAthleteShareRequest) (*RevokeAthleteShareResponse, error)
	// F7P4.1 — Annual Forge Almanac. Renders a multi-page PDF of the lifter's
	// training year (rank + stats + PR board + tonnage) to R2 + media_assets,
	// returns the public URL.
	GenerateForgeAlmanac(context.Context, *GenerateForgeAlmanacRequest) (*GenerateForgeAlmanacResponse, error)
	// F7P4.2 — AI form-check. Runs a pose-heuristic pass over an uploaded form
	// video and writes a one-line cue + verdict, flipping the clip to
	// 'reviewed'. Heuristic until the Gemini vision pass is wired.
	AnalyzeFormVideo(context.Context, *AnalyzeFormVideoRequest) (*AnalyzeFormVideoResponse, error)
	// F7P5.1 — rivalry creation (challenge by handle, or a named rival).
	CreateRivalry(context.Context, *CreateRivalryRequest) (*CreateRivalryResponse, error)
	// F7P5.2 — leaderboard standings (ranked by forge_rank). The scheduled
	// Sunday clout-drop publish is a separate cron job; this is the live query.
	GetLeaderboard(context.Context, *GetLeaderboardRequest) (*GetLeaderboardResponse, error)
	// F7P5.3 — Forge Lounge: physical recovery-room directory + booking flow.
	ListForgeLounges(context.Context, *ListForgeLoungesRequest) (*ListForgeLoungesResponse, error)
	ListMyLoungeBookings(context.Context, *ListMyLoungeBookingsRequest) (*ListMyLoungeBookingsResponse, error)
	CreateLoungeBooking(context.Context, *CreateLoungeBookingRequest) (*CreateLoungeBookingResponse, error)
	CancelLoungeBooking(context.Context, *CancelLoungeBookingRequest) (*CancelLoungeBookingResponse, error)
	// F7P5.4 — coach directory + booking request. Payment-backed booking is
	// deferred (Stripe); RequestCoachBooking files an interest request a coach
	// can pick up.
	ListCoaches(context.Context, *ListCoachesRequest) (*ListCoachesResponse, error)
	RequestCoachBooking(context.Context, *RequestCoachBookingRequest) (*RequestCoachBookingResponse, error)
	mustEmbedUnimplementedWorkoutServiceServer()
}

